-- FreePromptLibraryAI: Supabase setup
-- Run this entire file once in Supabase Dashboard > SQL Editor.
-- It does NOT create an admin account: it uses the admin_users row you already added.

create extension if not exists pgcrypto;

create table if not exists public.admin_users (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.admin_users enable row level security;
drop policy if exists "Admins can read own record" on public.admin_users;
create policy "Admins can read own record" on public.admin_users
  for select to authenticated using (auth.uid() = user_id);
grant select on public.admin_users to authenticated;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.admin_users
    where user_id = (select auth.uid())
  );
$$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

create table if not exists public.prompts (
  id bigint generated by default as identity primary key,
  title text not null,
  title_hi text not null default '',
  type text not null default 'Photo' check (type in ('Photo','Video')),
  category text not null default 'General',
  prompt_en text not null default '',
  prompt_hi text not null default '',
  aspect_ratio text not null default '',
  duration text not null default '',
  image_url text not null default '',
  is_trending boolean not null default false,
  status text not null default 'draft' check (status in ('draft','published')),
  extra_sections jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists prompts_status_id_idx on public.prompts(status, id desc);
create index if not exists prompts_trending_idx on public.prompts(is_trending) where status='published';
alter table public.prompts enable row level security;
drop policy if exists "Published prompts are visible" on public.prompts;
drop policy if exists "Admins can insert prompts" on public.prompts;
drop policy if exists "Admins can update prompts" on public.prompts;
drop policy if exists "Admins can delete prompts" on public.prompts;
create policy "Published prompts are visible" on public.prompts
  for select to anon, authenticated using (status = 'published' or public.is_admin());
create policy "Admins can insert prompts" on public.prompts
  for insert to authenticated with check (public.is_admin());
create policy "Admins can update prompts" on public.prompts
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins can delete prompts" on public.prompts
  for delete to authenticated using (public.is_admin());
grant select on public.prompts to anon, authenticated;
grant insert, update, delete on public.prompts to authenticated;
grant usage, select on sequence public.prompts_id_seq to authenticated;

-- Public sample images; only admins may upload/change/delete files.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('prompt-images', 'prompt-images', true, 5242880, array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set public=true, file_size_limit=5242880,
  allowed_mime_types=array['image/jpeg','image/png','image/webp','image/avif'];
drop policy if exists "Prompt images are public" on storage.objects;
drop policy if exists "Admins upload prompt images" on storage.objects;
drop policy if exists "Admins update prompt images" on storage.objects;
drop policy if exists "Admins delete prompt images" on storage.objects;
create policy "Prompt images are public" on storage.objects
  for select to public using (bucket_id = 'prompt-images');
create policy "Admins upload prompt images" on storage.objects
  for insert to authenticated with check (bucket_id = 'prompt-images' and public.is_admin());
create policy "Admins update prompt images" on storage.objects
  for update to authenticated using (bucket_id = 'prompt-images' and public.is_admin())
  with check (bucket_id = 'prompt-images' and public.is_admin());
create policy "Admins delete prompt images" on storage.objects
  for delete to authenticated using (bucket_id = 'prompt-images' and public.is_admin());

