  (30 , 'Mountain Drone Flyover', 'पहाड़ों के ऊपर ड्रोन फ्लायओवर', 'Video', 'Cinematic', 'Create a 10-second cinematic drone flyover above mountain peaks at sunrise. Use realistic clouds and smooth forward motion.', 'सूर्योदय में पहाड़ों के ऊपर बादलों के बीच से गुजरता 10 सेकंड का स्मूद ड्रोन वीडियो बनाएं।', '9:16', '8–10 seconds', 'published', false),
  (31 , 'Dance Reel', 'डांस रील वीडियो', 'Video', 'Dance', 'Create a 10-second vertical dance video featuring the supplied character. Preserve appearance and outfit. Use full-body framing and natural rhythmic movement.', 'दिए गए कैरेक्टर का लुक और कपड़े सुरक्षित रखते हुए 9:16 में 10 सेकंड का डांस वीडियो बनाएं।', '9:16', '8–10 seconds', 'published', false),
  (32 , 'Street Interview', 'स्ट्रीट इंटरव्यू वीडियो', 'Video', 'Social Media', 'Create a 10-second vertical street interview scene with an interviewer and guest, natural gestures and lively public background.', 'इंटरव्यू लेने वाले और मेहमान के साथ 9:16 में 10 सेकंड का स्वाभाविक स्ट्रीट इंटरव्यू वीडियो बनाएं।', '9:16', '8–10 seconds', 'published', false),
  (33 , 'YouTube Intro', 'यूट्यूब चैनल इंट्रो', 'Video', 'YouTube', 'Create a 7-second energetic YouTube channel intro using the supplied name and logo. Keep text readable and finish with a clean brand lockup.', 'दिए गए चैनल नाम और लोगो के साथ 7 सेकंड का एनर्जेटिक यूट्यूब इंट्रो बनाएं। टेक्स्ट साफ रखें।', '9:16', '8–10 seconds', 'published', false),
